insert into jhk_private.questions(id,payload) select item->>'id',item from jsonb_array_elements($jhk_bank$[{"id":"cr600","prompt":{"en":"What did Shakib Al Hasan admit in the ICC case settled in October 2019?"},"options":[{"en":"Not reporting corrupt approaches"},{"en":"Falsifying his age documents"},{"en":"Tampering with a match ball"},{"en":"Refusing a doping test"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"simple","files":["sports","cricket","spicy"],"correctIndex":0,"explanation":{"en":"He accepted three failures to report approaches. The decision did not find that he had fixed a match. The two-year sanction included one suspended year."},"sourceUrl":"https://www.icc-cricket.com/media-releases/shakib-al-hasan-banned-after-accepting-three-charges-under-icc-anti-corruption-code"},{"id":"cr601","prompt":{"en":"Of Shakib Al Hasan’s two-year sanction announced in 2019, how much was suspended?"},"options":[{"en":"Six months"},{"en":"One year"},{"en":"Eighteen months"},{"en":"None"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"expert","files":["sports","cricket","spicy"],"correctIndex":1,"explanation":{"en":"One year was suspended subject to conditions. The agreed sanction concerned failures to disclose corrupt approaches, not a finding of match-fixing."},"sourceUrl":"https://www.icc-cricket.com/media-releases/shakib-al-hasan-banned-after-accepting-three-charges-under-icc-anti-corruption-code"},{"id":"cr602","prompt":{"en":"What was central to Sanath Jayasuriya’s admitted breaches in the ICC decision of February 2019?"},"options":[{"en":"A disputed bowling action"},{"en":"An equipment sponsorship dispute"},{"en":"Non-cooperation and obstruction of an investigation"},{"en":"A team-selection eligibility error"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"expert","files":["sports","cricket","spicy"],"correctIndex":2,"explanation":{"en":"The ICC imposed a two-year sanction for failures to cooperate and obstruction or delay. Those specified findings should not be described as a match-fixing conviction."},"sourceUrl":"https://www.icc-cricket.com/media-releases/sanath-jayasuriya-banned-from-all-cricket-for-two-years"},{"id":"cr603","prompt":{"en":"Marlon Samuels’s six-year sanction in November 2023 was imposed under which board’s anti-corruption code?"},"options":[{"en":"Cricket West Indies"},{"en":"Cricket Australia"},{"en":"Sri Lanka Cricket"},{"en":"Emirates Cricket Board"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"extreme","files":["sports","cricket","spicy"],"correctIndex":3,"explanation":{"en":"The ICC acted as the designated anti-corruption official under the Emirates Cricket Board code. A tribunal found four disclosure, cooperation and obstruction offences."},"sourceUrl":"https://www.icc-cricket.com/media-releases/marlon-samuels-banned-for-six-years-under-anti-corruption-code"},{"id":"cr604","prompt":{"en":"In the Samuels tribunal findings announced in 2023, the undisclosed-hospitality charge specified a value of at least how much?"},"options":[{"en":"US$750"},{"en":"US$75"},{"en":"US$7,500"},{"en":"US$75,000"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"extreme","files":["sports","cricket","spicy"],"correctIndex":0,"explanation":{"en":"The tribunal unanimously found a failure to disclose hospitality valued at US$750 or more. This was one of four findings; the published decision does not establish a fixed match."},"sourceUrl":"https://www.icc-cricket.com/media-releases/marlon-samuels-banned-for-six-years-under-anti-corruption-code"},{"id":"cr605","prompt":{"en":"What did the ICC explicitly say about match outcomes when announcing Heath Streak’s sanction in April 2021?"},"options":[{"en":"All relevant results were annulled"},{"en":"The offences did not affect the outcomes"},{"en":"Every relevant game was replayed"},{"en":"The tournament winner was changed"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"expert","files":["sports","cricket","spicy"],"correctIndex":1,"explanation":{"en":"Streak admitted five breaches involving inside information, introductions, non-disclosure and obstruction. The ICC expressly stated that the offences did not affect relevant match outcomes."},"sourceUrl":"https://www.icc-cricket.com/media-releases/heath-streak-banned-for-eight-years-under-icc-anti-corruption-code"},{"id":"cr606","prompt":{"en":"According to the 2021 ICC decision, Heath Streak facilitated or attempted introductions involving how many players?"},"options":[{"en":"Two"},{"en":"Three"},{"en":"Four"},{"en":"Six"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"extreme","files":["sports","cricket","spicy"],"correctIndex":2,"explanation":{"en":"The decision described introductions involving four players to a potential corruptor. It did not say those players accepted corrupt proposals, and their identities are not quiz material here."},"sourceUrl":"https://www.icc-cricket.com/media-releases/heath-streak-banned-for-eight-years-under-icc-anti-corruption-code"},{"id":"cr607","prompt":{"en":"How long was Brendan Taylor’s anti-corruption suspension announced in January 2022?"},"options":[{"en":"Six months"},{"en":"One year"},{"en":"Two years"},{"en":"Three and a half years"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"expert","files":["sports","cricket","spicy"],"correctIndex":3,"explanation":{"en":"Taylor accepted four anti-corruption breaches. The suspension ended in July 2025; a separate one-month anti-doping sanction ran concurrently, not on top of it."},"sourceUrl":"https://www.icc-cricket.com/news/brendan-taylor-banned-under-icc-anti-corruption-code-and-anti-doping-code"},{"id":"cr608","prompt":{"en":"After completing his suspension in 2025, Brendan Taylor returned to Zimbabwe’s Test squad to face which side?"},"options":[{"en":"New Zealand"},{"en":"Australia"},{"en":"Pakistan"},{"en":"South Africa"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"simple","files":["sports","cricket","spicy"],"correctIndex":0,"explanation":{"en":"Zimbabwe named him for the second Test against New Zealand after he became eligible again. A historical sanction should not be presented as an ongoing ban after completion."},"sourceUrl":"https://www.icc-cricket.com/news/zimbabwe-announce-squad-for-second-test-against-new-zealand"},{"id":"cr609","prompt":{"en":"The 2021 tribunal findings against Mohammad Naveed and Shaiman Anwar concerned attempts to corrupt which ICC event?"},"options":[{"en":"The 2017 Champions Trophy"},{"en":"The 2019 Men’s T20 World Cup Qualifier"},{"en":"The 2015 Men’s World Cup"},{"en":"The 2020 Under-19 World Cup"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"expert","files":["sports","cricket","spicy"],"correctIndex":1,"explanation":{"en":"Both were found guilty in relation to the 2019 qualifier and received eight-year bans. Naveed also faced findings under the separate T10 League code."},"sourceUrl":"https://www.icc-cricket.com/media-releases/naveed-and-shaiman-banned-for-eight-years-each-under-icc-anti-corruption-code"},{"id":"cr610","prompt":{"en":"Devon Thomas’s agreed sanction announced in May 2024 covered anti-corruption breaches across how many franchise leagues?"},"options":[{"en":"One"},{"en":"Two"},{"en":"Three"},{"en":"Four"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"extreme","files":["sports","cricket","spicy"],"correctIndex":2,"explanation":{"en":"The admitted breaches involved the Lanka Premier League, Abu Dhabi T10 and Caribbean Premier League. The ICC acted under the respective domestic codes."},"sourceUrl":"https://www.icc-cricket.com/media-releases/devon-thomas-banned-for-five-years-under-anti-corruption-code"},{"id":"cr611","prompt":{"en":"How much of Devon Thomas’s five-year period of ineligibility announced in 2024 was suspended?"},"options":[{"en":"Six months"},{"en":"Twelve months"},{"en":"Twenty-four months"},{"en":"Eighteen months"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"extreme","files":["sports","cricket","spicy"],"correctIndex":3,"explanation":{"en":"The ICC suspended the last 18 months. The sanction was backdated to his provisional suspension on 23 May 2023 and followed seven admitted breaches."},"sourceUrl":"https://www.icc-cricket.com/media-releases/devon-thomas-banned-for-five-years-under-anti-corruption-code"},{"id":"cr612","prompt":{"en":"What length of Cricket Australia suspension did Cameron Bancroft accept in April 2018?"},"options":[{"en":"Nine months"},{"en":"Three months"},{"en":"Six months"},{"en":"Eighteen months"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"simple","files":["sports","cricket","spicy"],"correctIndex":0,"explanation":{"en":"Bancroft accepted a nine-month suspension for his part in the Cape Town ball-tampering incident. Smith and Warner received separate twelve-month playing suspensions."},"sourceUrl":"https://www.cricket.com.au/news/3290437/bancroft-accepts-ca-sanction"},{"id":"cr613","prompt":{"en":"What happened to David Warner’s Australian leadership ban after the review announced in October 2024?"},"options":[{"en":"It became a playing ban"},{"en":"It was lifted"},{"en":"It was extended by five years"},{"en":"It became a coaching-only ban"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"simple","files":["sports","cricket","spicy"],"correctIndex":1,"explanation":{"en":"An independent panel unanimously modified the 2018 sanction, restoring leadership eligibility. Describing the original lifetime restriction without this later outcome would be misleading."},"sourceUrl":"https://www.cricket.com.au/news/4155165"},{"id":"cr614","prompt":{"en":"Which item was at the centre of Faf du Plessis’s 2016 Hobart ball-tampering case?"},"options":[{"en":"A bottle cap"},{"en":"A nail file"},{"en":"A mint"},{"en":"A strip of tape"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"simple","files":["sports","cricket","spicy"],"correctIndex":2,"explanation":{"en":"The ruling concerned residue from a mint transferred to the ball. Du Plessis contested the interpretation; his appeal was rejected in December 2016."},"sourceUrl":"https://www.cricket.com.au/news/3274824/icc-hands-down-faf-du-plessis-verdict"},{"id":"cr615","prompt":{"en":"After Faf du Plessis’s 2016 appeal was rejected, which penalty remained in place?"},"options":[{"en":"A twelve-month playing suspension"},{"en":"A two-Test suspension"},{"en":"A lifetime captaincy restriction"},{"en":"A full match-fee fine and three demerit points"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"expert","files":["sports","cricket","spicy"],"correctIndex":3,"explanation":{"en":"The 100% match-fee fine and three demerit points stood. He remained eligible for the next Test; the appeal did not add a suspension."},"sourceUrl":"https://www.cricket.com.au/news/3274824/icc-hands-down-faf-du-plessis-verdict"},{"id":"cr616","prompt":{"en":"Whose committee’s interim report did the BCCI say it would fully implement when confirming the 2015 IPL franchise suspensions?"},"options":[{"en":"Justice Lodha’s"},{"en":"Justice Mudgal’s"},{"en":"Justice Srikrishna’s"},{"en":"Justice Verma’s"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"extreme","files":["sports","cricket","spicy"],"correctIndex":0,"explanation":{"en":"The October 2015 BCCI advisory named the Justice Lodha committee and confirmed two-year suspensions for CSK and RR. Franchise sanctions are not findings against every player in those squads."},"sourceUrl":"https://www.iplt20.com/news/article/bcci-to-invite-bids-for-two-new-ipl-teams"},{"id":"cr617","prompt":{"en":"What was the appeal outcome for the racial-abuse charge against Harbhajan Singh after the 2008 Sydney Test?"},"options":[{"en":"The three-Test ban was doubled"},{"en":"It was not proven; a lesser abuse charge drew a fine"},{"en":"A lifetime playing ban replaced it"},{"en":"The appeal was withdrawn without a decision"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"expert","files":["sports","cricket","spicy"],"correctIndex":1,"explanation":{"en":"Justice John Hansen found the level 3.3 charge not proven. Harbhajan pleaded guilty to the lesser abusive-language charge and was fined 50% of his match fee. The original allegation is not a sustained finding."},"sourceUrl":"https://www.icc-cricket.com/news/icc-statement-following-the-conclusion-of-harbhajan-singhs-independent-appeal-hearing"},{"id":"cr618","prompt":{"en":"What governance issue did the ICC cite when suspending Zimbabwe Cricket in July 2019?"},"options":[{"en":"A shortage of Test grounds"},{"en":"A broadcast-rights dispute"},{"en":"Government interference"},{"en":"A disagreement over shirt colours"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"simple","files":["sports","cricket","spicy"],"correctIndex":2,"explanation":{"en":"The ICC cited failures involving free elections and government interference. Zimbabwe was readmitted in October 2019, so this is a dated governance episode, not a current suspension."},"sourceUrl":"https://www.icc-cricket.com/media-releases/icc-board-and-full-council-concludes-in-london"},{"id":"cr619","prompt":{"en":"Which other cricket board was conditionally readmitted alongside Zimbabwe in October 2019?"},"options":[{"en":"Oman"},{"en":"Scotland"},{"en":"Namibia"},{"en":"Nepal"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"extreme","files":["sports","cricket","spicy"],"correctIndex":3,"explanation":{"en":"Nepal was conditionally reinstated after elections to its cricket association. Zimbabwe’s readmission followed its separate July 2019 suspension."},"sourceUrl":"https://www.icc-cricket.com/news/zimbabwe-and-nepal-readmitted-womens-event-prize-money-receives-a-major-boost"},{"id":"cr620","prompt":{"en":"How did future spouses Mitchell Starc and Alyssa Healy first meet, according to Cricket Australia’s 2016 wedding report?"},"options":[{"en":"As opponents in junior cricket"},{"en":"At a university lecture"},{"en":"On an Australia media tour"},{"en":"At a television award show"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"simple","files":["sports","cricket","spicy"],"correctIndex":0,"explanation":{"en":"They met as nine-year-old junior-cricket opponents and later shared wicketkeeping duties in an under-11 side. Both publicly celebrated their marriage in April 2016."},"sourceUrl":"https://www.cricket.com.au/news/3271084/shes-a-keeper-starc-and-healy-tie-the-knot"},{"id":"cr621","prompt":{"en":"Which hashtag did Mitchell Starc and Alyssa Healy use to celebrate their wedding in 2016?"},"options":[{"en":"#HealyStar"},{"en":"#stealy"},{"en":"#TeamMitch"},{"en":"#Starlyssa"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"extreme","files":["sports","cricket","spicy"],"correctIndex":1,"explanation":{"en":"Their public wedding posts used #stealy, combining their surnames. This is a voluntarily shared celebration, not a claim about private relationship drama."},"sourceUrl":"https://www.cricket.com.au/news/3271084/shes-a-keeper-starc-and-healy-tie-the-knot"},{"id":"cr622","prompt":{"en":"While dedicating his September 2022 comeback century to Anushka Sharma, which gesture did Virat Kohli say he made?"},"options":[{"en":"Pointed at his shirt number"},{"en":"Drew a heart on the pitch"},{"en":"Kissed his ring"},{"en":"Held up a handwritten sign"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"simple","files":["sports","cricket","spicy"],"correctIndex":2,"explanation":{"en":"Kohli described kissing his ring and dedicated the century to Anushka Sharma and their family, crediting her support. This reflects his own public account."},"sourceUrl":"https://www.icc-cricket.com/news/kohli-reflects-on-tough-times-after-ending-century-drought"},{"id":"cr623","prompt":{"en":"In their joint interview after the 2017 IPL final, which coach from home did the Pandya brothers specially thank?"},"options":[{"en":"John Wright"},{"en":"Gary Kirsten"},{"en":"Rahul Dravid"},{"en":"Jitendra Singh"}],"category":"Cricket","domain":"sports","topic":"Cricket","subtopic":"Spicy","difficulty":"expert","files":["sports","cricket","spicy"],"correctIndex":3,"explanation":{"en":"Hardik and Krunal thanked Jitendra Singh for their development and described their mutual support. The interview also credited Kiran More’s academy and their family."},"sourceUrl":"https://www.iplt20.com/news/article/i-am-proud-of-krunal-hardik-pandya"}]$jhk_bank$::jsonb) item on conflict(id) do update set payload=excluded.payload;
